/bin/zsh -c "python3 - <<'PY'
import json,collections
fees=json.load(open('inputs/fees.json'))
# Show rules relevant ID 384, GlobalCard credit, account H MCC 5812
print('ID 384:', next(r for r in fees if r['ID']==384))
print('\\nGlobalCard is_credit true examples')
for r in [x for x in fees if x['card_scheme']=='GlobalCard' and x['is_credit'] is True][:15]: print(r)
print('\\nH, MCC 5812 candidates')
for r in fees:
 if (r['account_type']==[] or 'H' in r['account_type']) and (r['merchant_category_code']==[] or 5812 in r['merchant_category_code']):
  if r['card_scheme']=='GlobalCard': print(r)
PY"

