/bin/zsh -c "python3 - <<'PY'
# count Belles distinct dimension combos and all transactions months
import csv,collections
for month,lo,hi in [('Jan',1,31),('Mar',60,90)]:
 c=collections.Counter(); n=0
 with open('inputs/payments.csv',newline='') as f:
  for r in csv.DictReader(f):
   if r['merchant']=='Belles_cookbook_store' and lo<=int(r['day_of_year'])<=hi:
    c[(r['card_scheme'],r['is_credit'],r['aci'],r['issuing_country']==r['acquirer_country'])]+=1;n+=1
 print(month,n,len(c))
 for k,v in sorted(c.items()):print(k,v)
PY"

