F=json.load(open('inputs/fees.json'))
md=next(x for x in json.load(open('inputs/merchant_data.json')) if x['merchant']=='Belles_cookbook_store')
def cdm(cd):
 v=md['capture_delay']; return cd is None or cd==('>5' if v=='7' else '<3' if v in ('1','2') else v)
def base(r):
 return (not r['account_type'] or md['account_type'] in r['account_type']) and cdm(r['capture_delay']) and (not r['merchant_category_code'] or md['merchant_category_code'] in r['merchant_category_code'])
